package p

type Buf struct {
	s []int
}

var s S

type S struct {
	buf Buf
}

// del removes element i from p.s. Its body mentions the parameter p twice.
//
//go:fix inline
func del(p *Buf, i int) {
	p.s = append(p.s[:i], p.s[i+1:]...)
}

func (s *S) run() {
	// Two inlinable calls in the SAME block, both with the address-of-a-field
	// argument &s.buf.
	del(&s.buf, 0)
	del(&s.buf, 0)
}
```

